  ('ute_hora_av_mig_01', 'ute', 10, 13, 1, 'Höra av mig när jag kommer fram', 'Höra av sig när man kommer fram eller blir sen', '📱', 'Kom överens om ett enkelt meddelande, till exempel en emoji.', true, array['ansvar', 'vana']::text[], true, 'star'),
  ('ute_grillplats_01', 'ute', 10, 13, 2, 'Tända en brasa med vuxen', 'Tända en brasa på en grillplats tillsammans med en vuxen', '🔥', 'Gå igenom eldningsförbud, vatten i närheten och hur man släcker.', false, array['friluftsliv', 'säkerhet']::text[], true, 'star'),
  ('pengar_veckopeng_manad_01', 'pengar', 10, 13, 2, 'Hantera min veckopeng en månad', 'Hantera sin egen veckopeng en hel månad', '💰', 'Låt barnet göra egna val, även misstag. Det är så man lär sig.', false, array['budget', 'ansvar']::text[], false, 'star'),
  ('pengar_jamfora_priser_01', 'pengar', 10, 13, 2, 'Jämföra priser och välja bästa köp', 'Jämföra priser och välja det bästa köpet', '⚖️', 'Jämför samma vara i två butiker eller på nätet.', false, array['handla', 'matte']::text[], false, 'star'),
  ('pengar_jamforpris_01', 'pengar', 10, 13, 1, 'Förstå jämförpris', 'Använda jämförpris (kr per kg) i affären', '🏷️', 'Visa var jämförpriset står på hyllkanten.', false, array['handla', 'matte']::text[], true, 'star'),
  ('pengar_sparmal_01', 'pengar', 10, 13, 2, 'Sätta ett sparmål', 'Sätta upp ett sparmål och följa det', '🎯', 'Rita eller gör ett kalkylark som visar hur nära målet barnet är.', false, array['spara', 'planering']::text[], true, 'star'),
  ('pengar_kvitto_01', 'pengar', 10, 13, 1, 'Kontrollera ett kvitto', 'Läsa och kontrollera ett kvitto', '🧾', 'Gå igenom ett kvitto efter handlingen tillsammans.', false, array['handla', 'matte']::text[], true, 'star'),
  ('pengar_betala_digitalt_01', 'pengar', 11, 13, 2, 'Betala med kort eller app', 'Betala med kort eller mobil med förälderns koll', '💳', 'Prata om att digitala pengar är riktiga pengar.', false, array['pengar', 'digitalt']::text[], true, 'star'),
  ('pengar_tjana_pengar_01', 'pengar', 10, 13, 3, 'Tjäna egna pengar', 'Tjäna egna pengar, till exempel genom att sälja saker', '💪', 'Hjälp till att hitta en idé, men låt barnet driva den.', false, array['entreprenör', 'pengar']::text[], true, 'star'),
  ('pengar_budget_utflykt_01', 'pengar', 10, 13, 2, 'Göra en budget för en utflykt', 'Göra en budget för en familjeutflykt', '📊', 'Ge en summa och låt barnet planera vad den räcker till.', false, array['budget', 'planering']::text[], true, 'star'),
  ('kanslor_boka_tid_01', 'kanslor', 10, 13, 2, 'Boka en egen tid', 'Boka en egen tid, till exempel hos frisören', '📅', 'Skriv ner vad barnet ska säga om det känns svårt.', false, array['socialt', 'telefon']::text[], false, 'star'),
  ('kanslor_halla_lofte_01', 'kanslor', 10, 13, 2, 'Hålla ett löfte en hel vecka', 'Hålla ett löfte en hel vecka', '🤞', 'Låt barnet själv välja löftet.', false, array['ansvar', 'tillit']::text[], false, 'star'),
