  ('kanslor_hjalpa_yngre_01', 'kanslor', 10, 13, 1, 'Hjälpa någon yngre', 'Hjälpa en yngre elev eller ett syskon med läxa eller lek', '🧑‍🏫', 'Beröm tålamodet och omtanken.', false, array['omtanke', 'ansvar']::text[], true, 'praise'),
  ('kanslor_stalla_till_ratta_01', 'kanslor', 10, 13, 2, 'Be om ursäkt och ställa till rätta', 'Be om ursäkt och göra något för att ställa till rätta', '🤝', 'Prata om skillnaden mellan att säga förlåt och att laga det som gick sönder.', false, array['socialt', 'ansvar']::text[], true, 'praise'),
  ('kanslor_mejla_lararen_01', 'kanslor', 11, 13, 2, 'Skriva ett mejl till läraren', 'Skriva ett mejl till läraren och fråga något', '📧', 'Gå igenom hälsning, fråga och avslutning.', false, array['skola', 'skriva']::text[], true, 'star'),
  ('kanslor_ta_emot_feedback_01', 'kanslor', 11, 13, 2, 'Ta emot feedback lugnt', 'Lyssna på feedback utan att bli arg', '🧘', 'Visa själv hur du tar emot feedback.', false, array['känslor', 'självkontroll']::text[], true, 'praise'),
  ('kanslor_skarmgranser_01', 'kanslor', 10, 13, 2, 'Sätta egna skärmgränser en vecka', 'Själv stänga av skärmen vid överenskommen tid en vecka', '📵', 'Kom överens om tiden tillsammans. Låt barnet själv hålla koll.', true, array['skärm', 'självkontroll']::text[], true, 'star'),
  ('mod_ny_aktivitet_01', 'mod', 10, 13, 2, 'Prova en ny aktivitet eller sport', 'Prova en ny aktivitet eller sport', '🏄', 'Det är modigt att vara nybörjare. Prata om det!', false, array['nytt', 'rörelse']::text[], false, 'star'),
