  ('mod_lager_01', 'mod', 10, 13, 3, 'Åka på läger', 'Åka på läger eller övernattning med en förening', '⛺', 'Packa tillsammans och prata om hur man gör om man längtar hem.', false, array['nytt', 'trygghet']::text[], true, 'star'),
  ('mod_upptrada_01', 'mod', 10, 13, 3, 'Uppträda inför publik', 'Uppträda inför publik, till exempel på en skolavslutning', '🎭', 'Öva många gånger hemma och fira efteråt oavsett hur det gick.', false, array['scen', 'mod']::text[], true, 'star'),
  ('mod_hopptorn_01', 'mod', 10, 13, 3, 'Hoppa från hopptornet', 'Hoppa från ett hopptorn i simhallen', '🤸', 'Börja från en låg höjd. Inget tvång.', false, array['vatten', 'mod']::text[], true, 'star'),
